open Thread;;

(*QUESTION 4*)

(*Condition : arbre de profondeur N, children et occurences doivent avoir la meme taille*)
type node = {
  etiquette : char;
  mutable children : node list;
  mutable occurences : int list;
  mutable total_occurences : int
}
(*((opti possible : prendre les sous-mots à l'envers))*)

(*QUESTION 5*)
let new_leaf (a : char) : node =
  (*Façon qu'on utilisera pour créer tout arbre (de profondeur 1 et d'etiquette a)*)
  {etiquette = a; children = []; occurences = []; total_occurences=0}

let rec string_sub (text:string) (pos:int) (n:int) : string =
  (*Renvoie le sous-mot de taille au plus n commençant à la position pos de text*)
  match n with 
  |0 -> ""
  |_ when String.length text < pos+n -> "" 
  |_ -> (String.make 1 text.[pos]) ^ (string_sub text (pos+1) (n-1))

let add_successor (current_node : node) (successor : char) : node =
  (*Ajoute ou incrémente l'occurence de l'enfant successor du noeud et renvoie cet enfant et son occurence (occurence en tant que successeur de current_node).*)
  let rec aux l occurences_l pre_occurences_l=
    match l with
    |[]-> let leaf = new_leaf successor in 
    current_node.children <- (leaf :: (current_node.children)); current_node.occurences <- (1 :: (current_node.occurences)); leaf
    |h::_ when h.etiquette = successor -> let new_occ = (List.hd occurences_l)+1 in 
    current_node.occurences <- (pre_occurences_l @ [new_occ] @(List.tl occurences_l)); h
    |_::t -> aux t (List.tl occurences_l) (pre_occurences_l @ [List.hd occurences_l])
  in let chosen_node = aux (current_node.children) (current_node.occurences) [] in
  (*On fait en sorte que total_occurences reste corrects*)
  current_node.total_occurences <- (current_node.total_occurences +1);
  chosen_node

let add_n_upplet (root : node) (n_upplet : string) : unit =
  (*Ajoute un n_upplet à "l'arbre modele N gramme" en descendant dans l'arbre.
  Le n_upplet peut etre plus petit qu'un n_upplet, enfin bref...*)
  let current_node = ref root in
  for i = 0 to (String.length n_upplet -1) do
    current_node := add_successor (!current_node) n_upplet.[i];
  done

let construct_model (text:string) (n:int) : node =
  (*Pour faciliter l'implémentation, la racine est un noeud de l'arbre, son etiquette n'est pas importante.*)
  let root = new_leaf ' ' in
  for i = 0 to (String.length text - n) do
    let n_upplet = string_sub text i n in
    add_n_upplet root n_upplet;
  done;
  root

let print_profondeur (n : int) : unit =
  for _ = 1 to n-1 do
    Printf.printf "\t"
  done

let print_children (l : node list) (l_occ : int list) (profondeur : int) : unit =
  let rec aux l1 l2 =
    match l1 with 
    |[]->()
    |h::t -> let h_occ, t_occ = List.hd l2, List.tl l2 in print_profondeur profondeur; (Printf.printf "|%c avec %i occurences" h.etiquette h_occ) ; aux t t_occ
  in aux l l_occ; Printf.printf "\n"

let print_model (root : node) : unit =
  Printf.printf "--------Printing model----------\n\n";
  let rec aux l profondeur =
    match l with
    |[] -> ()
    |h::t -> print_children h.children h.occurences (profondeur+1); aux h.children (profondeur+1); aux t (profondeur)
  in aux [root] 1

