(*QUESTION 6*)
let search_in_children (n0 : node) (c : char) : node option =
  let l = n0.children in 
  let rep = ref None in
  let aux elt = if elt.etiquette=c then rep:= Some elt in  
  List.iter aux l;
  !rep

let rec predit_i_upplet (modele : node) (ss_mot : string) : char option =
  (*Get random successor*)
  if (String.length ss_mot = 0) then(
    if (modele.total_occurences = 0) then
      None
    else (
      let chosen = ref (Random.int modele.total_occurences) in
      let rep_ind = ref (-1) in
      let rep = ref None in
      let aux ind elt =
        chosen := !chosen - elt;
        if (!chosen < 0 && !rep_ind = -1) then rep_ind := ind 
      in List.iteri aux modele.occurences ;
      List.iteri (fun i a -> (if i = !rep_ind then rep:=Some a.etiquette)) modele.children;
      !rep
    ) )   
  else (
    (*Look for first char of ss_mot in the children, if it is found, recall predit_i_upplet else return None*)
    match search_in_children modele ss_mot.[0] with
    |None -> None
    |Some n0 -> predit_i_upplet n0 (string_sub ss_mot 1 (String.length ss_mot -1))
  )

let prediction_step (modele : node) (sous_mot : string) : char option=
  (*On prend chaque sortie des 1 à n grammes puis on choisie aléatoirement l'un d'eux*)
  let possible_char = ref "" in
  let num_char = ref 0 in
  for i = 0 to String.length sous_mot -1 do
    let o = predit_i_upplet modele (string_sub sous_mot ((String.length sous_mot) -i-1) (i+1)) in
    match o with
    |None -> ()
    |Some c -> incr num_char; possible_char := (String.make 1 c) ^ (!possible_char)
  done;
  if !num_char = 0 then
    None
  else (
    let chosen_number = ref 0 in
    while (!num_char > 1) do
      decr num_char;
      let take_or_halve_it_and_give_it_to_the_next_person = Random.int 3 in
      if (take_or_halve_it_and_give_it_to_the_next_person = 0) then
        incr chosen_number
      else
        num_char := 0
    done;
    Some (!possible_char).[!chosen_number]
  )

exception Texte_vide

let prediction (modele : node) (n : int) (max_pred : int) (texte : string) : string =
  if String.length texte = 0 then 
    raise Texte_vide;
  let sous_mot = ref (string_sub texte (max 0 ((String.length texte) -n)) (min n (String.length texte))) in 
  let ind = ref 0 in
  let rep = ref "" in
  while(!ind < max_pred) do
    let o = prediction_step modele !sous_mot in
    match o with 
    |None -> ind:= max_pred
    |Some c -> incr ind; rep := !rep ^ (String.make 1 c); sous_mot := (string_sub !sous_mot 1 ((String.length !sous_mot)-1)) ^ (String.make 1 c)
  done;
  !rep

