(*QUESTION 7*)
let rec wait_threads (l : t list) : unit =
  match l with
  |[] -> ()
  |h::t -> Thread.join h; wait_threads t

let multi_learning (texte : string) (n:int) (num_agents : int) : node list =
  (*Renvoie une liste de num_agents arbres qui sont des n-gramme models*)
  (*On coupe le texte en num_agents ce qui est critiquable car certains n_upplets sont coupés*)
  let rep = ref [] in
  let taille_sous_textes = (String.length texte)/num_agents in 
  let th_list = ref [] in
  for i = 0 to num_agents-1 do
    let ss_texte = (string_sub texte (i*taille_sous_textes) taille_sous_textes) in
    let thread_fun (text : string) : unit =
      let new_tree = construct_model text n in
      rep := new_tree :: (!rep) 
    in
    let thread = Thread.create thread_fun ss_texte  in
    th_list := thread :: (!th_list);
  done;
  wait_threads (!th_list);
  !rep

