(*QUESTION 8*)
exception Children_occurences_depareilles

let rec fusion_deux_modeles (n1 : node) (n2 : node) : unit =
  (*Prérequis : les deux etiquettes sont les mêmes. 
  On fusionne donc les enfants de n1 et n2 un à un.
  La fusion est en n1*)
  assert(n1.etiquette = n2.etiquette);
  let rec aux l_c l_occ =
    match l_c, l_occ with 
    |[], []-> ()
    |h1::t1, h2::t2 -> fusion_one_child n1 h1 h2; aux t1 t2
    |_,_ -> raise Children_occurences_depareilles (*shouldn't happen*)
  in aux n2.children n2.occurences

and fusion_one_child (n1 : node) (child : node) (occ : int) : unit =
  (*Cherche child parmis les enfants de n1 et fusionne s'il trouve sinon child est ajouté à n1.children. 
  Dans tous les cas occ s'ajoute correctement dans n1.occurences et n1.total_occurences est également bien incrémenté. 
  En cas de fusion, on lance fusion_deux_modeles sur les deux enfants fusionné.*)
  n1.total_occurences <- n1.total_occurences + occ;
  let child_ind = ref (-1) in
  let f_iteri_children i a =
    if (a.etiquette = child.etiquette) then 
      (
        fusion_deux_modeles a child; 
        child_ind := i
      ) in
  List.iteri f_iteri_children n1.children;
  if (!child_ind = -1) then (*S'il n'y a pas eu de fusion*)
    (n1.children <- child :: n1.children;
    n1.occurences <- occ :: n1.occurences)
  else ( (*S'il y a eu une fusion*)
    n1.occurences <- List.mapi (fun i a -> if(i= !child_ind)then a+occ else a) n1.occurences
  )

let  fusion (trees : node list) : node =
  let rec aux l fusion_so_far= 
    match l with
    |[] -> fusion_so_far
    |h::t -> fusion_deux_modeles fusion_so_far h ; aux t fusion_so_far
  in aux trees (new_leaf ' ')

