  let model_nodes = multi_learning training_text2 n num_agents in
  let tree_fusion = fusion model_nodes in
  Printf.printf "%s\n" (prediction tree_fusion n 100 "Hello I am a");
  (*Some small tests*)
  let total_occ = ref 0 in
  List.iter (fun a -> total_occ := !total_occ + a.total_occurences) model_nodes;
  assert(!total_occ = tree_fusion.total_occurences);
  assert(fusion [(new_leaf ' '); (new_leaf ' ')] = (new_leaf ' '))

